<?php
declare(strict_types=1);namespace App\Tests\Unit\Discovery;use App\Application\Discovery\DTO\Request\CreateDiscoverySearchRequestDto;use App\Application\Discovery\Mapper\DiscoveryResponseMapper;use App\Application\Discovery\Port\WebDiscoveryProviderInterface;use App\Application\Discovery\Service\DiscoverWebResourcesService;use App\Domain\Discovery\Entity\DiscoveryResource;use App\Domain\Discovery\Repository\DiscoveryResourceRepositoryInterface;use App\Domain\Discovery\ValueObject\DiscoveredResource;use PHPUnit\Framework\TestCase;final class DiscoverWebResourcesServiceTest extends TestCase{public function testLimitsAndPreservesProvenance():void{$repo=new class implements DiscoveryResourceRepositoryInterface{public array $saved=[];public function save(DiscoveryResource $r):void{$this->saved[]=$r;}public function list(?string $t=null):array{return[];}};$provider=new class implements WebDiscoveryProviderInterface{public function name():string{return'allowed';}public function search(string $q,string $t):array{return array_map(static fn($n)=>new DiscoveredResource($t,'Recurso '.$n,'https://allowed.test/'.$n),range(1,12));}};$result=(new DiscoverWebResourcesService($repo,$provider,new DiscoveryResponseMapper()))->discover(new CreateDiscoverySearchRequestDto('prova analista','EXAM'));self::assertCount(10,$result);self::assertSame('allowed',$result[0]->provider);self::assertSame('prova analista',$result[0]->queryText);}}
